"""Solver for the Zebra Puzzle.

Assigns one value from each category (nationality, color, pet, drink,
hobby) to each of the five houses so that all 15 clues hold, then
answers the two questions: which resident drinks water and who owns
the zebra.
"""

NATIONALITIES = ["Englishman", "Spaniard", "Ukrainian", "Japanese", "Norwegian"]
COLORS = ["red", "ivory", "green", "yellow", "blue"]
PETS = ["dog", "fox", "horse", "snail", "zebra"]
DRINKS = ["coffee", "tea", "milk", "orange juice", "water"]
HOBBIES = ["dancing", "painting", "reading", "football", "chess"]


def _solve():
    """Return the unique solution as a list of per-house dicts."""
    solution = [
        {
            "nationality": None,
            "color": None,
            "pet": None,
            "drink": None,
            "hobby": None,
        }
        for _ in range(5)
    ]

    def neighbors(house):
        if house > 0:
            yield house - 1
        if house < 4:
            yield house + 1

    def assign(category, house, value):
        """Assign value to house if the clue constraints still hold."""
        if solution[house][category] is not None:
            return solution[house][category] == value
        solution[house][category] = value
        ok = True
        # 2. The Englishman lives in the red house.
        if solution[house]["nationality"] == "Englishman":
            ok = solution[house]["color"] in (None, "red")
        # 3. The Spaniard owns the dog.
        if solution[house]["nationality"] == "Spaniard":
            ok = ok and solution[house]["pet"] in (None, "dog")
        # 4. The person in the green house drinks coffee.
        if solution[house]["color"] == "green":
            ok = ok and solution[house]["drink"] in (None, "coffee")
        # 5. The Ukrainian drinks tea.
        if solution[house]["nationality"] == "Ukrainian":
            ok = ok and solution[house]["drink"] in (None, "tea")
        # 6. The green house is immediately to the right of the ivory house.
        if solution[house]["color"] == "green" and house > 0:
            ok = ok and solution[house - 1]["color"] in (None, "ivory")
        if solution[house]["color"] == "ivory" and house < 4:
            ok = ok and solution[house + 1]["color"] in (None, "green")
        # 7. The snail owner likes to go dancing.
        if solution[house]["pet"] == "snail":
            ok = ok and solution[house]["hobby"] in (None, "dancing")
        # 8. The person in the yellow house is a painter.
        if solution[house]["color"] == "yellow":
            ok = ok and solution[house]["hobby"] in (None, "painting")
        # 11. The person who enjoys reading lives next to the person with
        #     the fox.
        if solution[house]["hobby"] == "reading":
            ok = ok and any(
                solution[n]["pet"] in (None, "fox") for n in neighbors(house)
            )
        if solution[house]["pet"] == "fox":
            ok = ok and any(
                solution[n]["hobby"] in (None, "reading") for n in neighbors(house)
            )
        # 12. The painter's house is next to the house with the horse.
        if solution[house]["hobby"] == "painting":
            ok = ok and any(
                solution[n]["pet"] in (None, "horse") for n in neighbors(house)
            )
        if solution[house]["pet"] == "horse":
            ok = ok and any(
                solution[n]["hobby"] in (None, "painting") for n in neighbors(house)
            )
        # 13. The person who plays football drinks orange juice.
        if solution[house]["hobby"] == "football":
            ok = ok and solution[house]["drink"] in (None, "orange juice")
        # 14. The Japanese person plays chess.
        if solution[house]["nationality"] == "Japanese":
            ok = ok and solution[house]["hobby"] in (None, "chess")
        if not ok:
            solution[house][category] = None
            return False
        return True

    def backtrack(house, category_index):
        if house == 5:
            return True
        if category_index == 0:
            # 10. The Norwegian lives in the first house.
            if not assign("nationality", house, "Norwegian"):
                return False
            return backtrack(house + 1, 0)
        category = ["nationality", "color", "pet", "drink", "hobby"][
            category_index
        ]
        for value in (
            NATIONALITIES,
            COLORS,
            PETS,
            DRINKS,
            HOBBIES,
        )[category_index]:
            if assign(category, house, value):
                if backtrack(house, category_index + 1):
                    return True
                solution[house][category] = None
        return False

    # 9. The person in the middle house drinks milk.
    # 15. The Norwegian lives next to the blue house (so house 2 is blue).
    solution[2]["drink"] = "milk"
    solution[1]["color"] = "blue"
    backtrack(0, 0)
    return solution


def _find(resident):
    """Return the house dict for the given resident."""
    for house in _solve():
        if house["nationality"] == resident:
            return house
    raise ValueError(f"resident {resident!r} not found")


def drinks_water():
    """Return the nationality of the resident who drinks water."""
    for house in _solve():
        if house["drink"] == "water":
            return house["nationality"]
    raise ValueError("no resident drinks water")


def owns_zebra():
    """Return the nationality of the resident who owns the zebra."""
    for house in _solve():
        if house["pet"] == "zebra":
            return house["nationality"]
    raise ValueError("no resident owns the zebra")

