"""Solver for the Zebra Puzzle.

Assigns one value from each category (nationality, color, pet, drink,
hobby) to each of the five houses so that all 15 clues hold, then
answers the two questions: which resident drinks water and who owns
the zebra.
"""

NATIONALITIES = ["Englishman", "Spaniard", "Ukrainian", "Japanese", "Norwegian"]
COLORS = ["red", "ivory", "green", "yellow", "blue"]
PETS = ["dog", "fox", "horse", "snail", "zebra"]
DRINKS = ["coffee", "tea", "milk", "orange juice", "water"]
HOBBIES = ["dancing", "painting", "reading", "football", "chess"]

CATEGORIES = ["nationality", "color", "pet", "drink", "hobby"]
VALUES = [NATIONALITIES, COLORS, PETS, DRINKS, HOBBIES]


def _verify(houses):
    """Return True if the complete assignment satisfies every clue."""

    def at(category, value):
        return [i for i, h in enumerate(houses) if h[category] == value]

    # Each category is a permutation of its five values.
    for category in CATEGORIES:
        values = [h[category] for h in houses]
        if len(set(values)) != 5:
            return False

    for h in houses:
        # 2. The Englishman lives in the red house.
        if h["nationality"] == "Englishman" and h["color"] != "red":
            return False
        # 3. The Spaniard owns the dog.
        if h["nationality"] == "Spaniard" and h["pet"] != "dog":
            return False
        # 4. The person in the green house drinks coffee.
        if h["color"] == "green" and h["drink"] != "coffee":
            return False
        # 5. The Ukrainian drinks tea.
        if h["nationality"] == "Ukrainian" and h["drink"] != "tea":
            return False
        # 7. The snail owner likes to go dancing.
        if h["pet"] == "snail" and h["hobby"] != "dancing":
            return False
        # 8. The person in the yellow house is a painter.
        if h["color"] == "yellow" and h["hobby"] != "painting":
            return False
        # 13. The person who plays football drinks orange juice.
        if h["hobby"] == "football" and h["drink"] != "orange juice":
            return False
        # 14. The Japanese person plays chess.
        if h["nationality"] == "Japanese" and h["hobby"] != "chess":
            return False

    # 6. The green house is immediately to the right of the ivory house.
    if at("color", "green")[0] != at("color", "ivory")[0] + 1:
        return False
    # 9. The person in the middle house drinks milk.
    if houses[2]["drink"] != "milk":
        return False
    # 10. The Norwegian lives in the first house.
    if houses[0]["nationality"] != "Norwegian":
        return False
    # 11. The person who enjoys reading lives next to the person with the fox.
    if abs(at("hobby", "reading")[0] - at("pet", "fox")[0]) != 1:
        return False
    # 12. The painter's house is next to the house with the horse.
    if abs(at("hobby", "painting")[0] - at("pet", "horse")[0]) != 1:
        return False
    # 15. The Norwegian lives next to the blue house.
    if houses[1]["color"] != "blue":
        return False
    return True


def _solve():
    """Return the unique solution as a list of per-house dicts."""
    solution = [dict.fromkeys(CATEGORIES) for _ in range(5)]

    def assign(category, house, value):
        """Assign value to house if it does not contradict a clue.

        These checks prune the search; _verify enforces the clues
        completely when a full assignment is reached.
        """
        if solution[house][category] is not None:
            return solution[house][category] == value
        # Each category value may appear in at most one house.
        for other in range(5):
            if other != house and solution[other][category] == value:
                return False
        solution[house][category] = value
        ok = True
        # 2. The Englishman lives in the red house.
        if solution[house]["nationality"] == "Englishman":
            ok = solution[house]["color"] in (None, "red")
        # 3. The Spaniard owns the dog.
        if solution[house]["nationality"] == "Spaniard":
            ok = ok and solution[house]["pet"] in (None, "dog")
        # 4. The person in the green house drinks coffee.
        if solution[house]["color"] == "green":
            ok = ok and solution[house]["drink"] in (None, "coffee")
        # 5. The Ukrainian drinks tea.
        if solution[house]["nationality"] == "Ukrainian":
            ok = ok and solution[house]["drink"] in (None, "tea")
        # 6. The green house is immediately to the right of the ivory house.
        if solution[house]["color"] == "green":
            ok = ok and house > 0
            ok = ok and solution[house - 1]["color"] in (None, "ivory")
            if house < 4:
                ok = ok and solution[house + 1]["color"] != "ivory"
        if solution[house]["color"] == "ivory":
            ok = ok and house < 4
